import { KJUR, RSAKey, X509 } from 'jsrsasign'
import { arrayBufferToBase64, getPublicKeyFromDERCertificate } from './cryptokey'
import { HsmSigner } from './signWithHsm'

export interface HsmSession extends HsmSigner {
  certBase64: string
  subject: string
}

let session: HsmSession | null = null
let enabled = false

// The session state is module scoped (it holds non-serializable provider
// handles), so listeners let React components re-render when it changes
const listeners = new Set<() => void>()

const emitChange = (): void => {
  listeners.forEach(listener => listener())
}

export const subscribeHsm = (listener: () => void): (() => void) => {
  listeners.add(listener)
  return () => {
    listeners.delete(listener)
  }
}

export const isHsmEnabled = (): boolean => enabled

export const hasHsmSession = (): boolean => session !== null

export const getHsmSession = (): HsmSession => {
  if (!session) {
    throw new Error('No HSM certificate selected. Enable signing with an HSM and select a certificate first.')
  }
  return session
}

export const getHsmPublicKey = (): string | undefined => (session ? getPublicKeyFromDERCertificate(session.certBase64) : undefined)

export const disableHsm = (): void => {
  enabled = false
  session = null
  // Removing the dialog element closes the Fortify connection
  document.getElementById('fortify-cert-container')?.remove()
  emitChange()
}

const CERTIFICATE_ALG_BY_CURVE: Record<string, string> = {
  secp256r1: 'ES256',
  'P-256': 'ES256',
  secp384r1: 'ES384',
  'P-384': 'ES384',
  secp521r1: 'ES512',
  'P-521': 'ES512'
}

function getCertificateAlgAndSubject(certBase64: string): { alg: string; subject: string } {
  const pemCertificate = `-----BEGIN CERTIFICATE-----\n${certBase64}\n-----END CERTIFICATE-----`
  const x509 = new X509()
  x509.readCertPEM(pemCertificate)
  const publicKey = x509.getPublicKey()

  let alg: string | undefined
  if (publicKey instanceof KJUR.crypto.ECDSA) {
    // curveName is a runtime property of jsrsasign ECDSA keys, absent from its type declarations
    const curveName = (publicKey as any).curveName as string
    alg = CERTIFICATE_ALG_BY_CURVE[curveName]
    if (!alg) {
      throw new Error(`Unsupported certificate elliptic curve: ${curveName}`)
    }
  } else if (publicKey instanceof RSAKey) {
    alg = 'RS256'
  } else {
    throw new Error('Unsupported certificate public key type, expected ECDSA or RSA')
  }
  return { alg, subject: x509.getSubjectString() }
}

// The Fortify web components are loaded from the CDN at the exact version
// pinned in package.json: their prebuilt distribution cannot be bundled by
// webpack (chunk imports are resolved at runtime) and their type declarations
// require TypeScript 5, while this project pins TypeScript 4.9. This is the
// same approach as the my-did reference implementation.
const FORTIFY_PACKAGE_VERSION = '4.2.0'
const FORTIFY_CDN_BASE_URL = `https://cdn.jsdelivr.net/npm/@peculiar/fortify-webcomponents@${FORTIFY_PACKAGE_VERSION}/dist/peculiar`

async function loadFortifyWebComponents(): Promise<void> {
  if (!document.querySelector('link[data-fortify-css]')) {
    const link = document.createElement('link')
    link.setAttribute('data-fortify-css', '')
    link.rel = 'stylesheet'
    link.href = `${FORTIFY_CDN_BASE_URL}/peculiar.css`
    document.head.appendChild(link)
  }
  if (!customElements.get('peculiar-fortify-certificates')) {
    await new Promise<void>((resolve, reject) => {
      const script = document.createElement('script')
      script.type = 'module'
      script.src = `${FORTIFY_CDN_BASE_URL}/peculiar.esm.js`
      script.onload = () => resolve()
      script.onerror = () => reject(new Error('Could not load the Fortify web components'))
      document.head.appendChild(script)
    })
  }
  await customElements.whenDefined('peculiar-fortify-certificates')
}

/**
 * Open the Fortify certificate selection dialog (the Fortify desktop app must
 * be running) and store the selected provider, private key handle and
 * certificate for the session. Returns null if the user cancels.
 */
export async function selectHsmCertificate(): Promise<HsmSession | null> {
  await loadFortifyWebComponents()

  let container = document.getElementById('fortify-cert-container')
  if (!container) {
    container = document.createElement('div')
    container.id = 'fortify-cert-container'
    // The Fortify dialog renders in normal flow, so the container acts as a
    // modal overlay to keep the dialog visible above the wizard.
    container.style.position = 'fixed'
    container.style.top = '0'
    container.style.left = '0'
    container.style.right = '0'
    container.style.bottom = '0'
    container.style.zIndex = '9999'
    container.style.display = 'flex'
    container.style.alignItems = 'center'
    container.style.justifyContent = 'center'
    document.body.appendChild(container)
  } else {
    container.style.display = 'flex'
  }
  const el = document.createElement('peculiar-fortify-certificates') as any
  container.replaceChildren()
  el.setAttribute('language', 'en')
  el.setAttribute('download-app-link', 'https://fortifyapp.com')
  container.appendChild(el)
  el.filters = { onlyWithPrivateKey: true, keyUsage: ['digitalSignature'] }

  const detail = await new Promise<any | null>(resolve => {
    const cleanup = () => {
      el.removeEventListener('selectionSuccess', onSuccess)
      el.removeEventListener('selectionCancel', onCancel)
    }
    const onSuccess = (e: any) => {
      cleanup()
      resolve(e.detail)
    }
    const onCancel = () => {
      cleanup()
      resolve(null)
    }
    el.addEventListener('selectionSuccess', onSuccess)
    el.addEventListener('selectionCancel', onCancel)
  })
  if (!detail) {
    // User cancelled: removing the dialog element closes the Fortify connection
    container.remove()
    return null
  }

  try {
    const provider = await detail.socketProvider.getCrypto(detail.providerId)
    const certificate = await provider.certStorage.getItem(detail.certificateId)
    let der: any = certificate.rawData
    if (!der) {
      der = await provider.certStorage.exportCert('raw', certificate)
    }
    const derBuffer: ArrayBuffer = der instanceof ArrayBuffer ? der : der.buffer.slice(der.byteOffset, der.byteOffset + der.byteLength)
    const certBase64 = arrayBufferToBase64(derBuffer)
    const privateKey = await provider.keyStorage.getItem(detail.privateKeyId)

    const { alg, subject } = getCertificateAlgAndSubject(certBase64)
    session = { provider, privateKey, certBase64, alg, subject }
    enabled = true
    emitChange()

    // Keep the dialog element mounted: the Fortify connection it owns is
    // needed to sign with the selected key, so only hide the overlay. Removing
    // the element would call the Fortify client finish() and close the socket.
    container.style.display = 'none'
    return session
  } catch (e) {
    container.remove()
    throw e
  }
}
